/**
 * Shared Give Protocol email branding (GIV-934).
 *
 * Single source of truth for the logo shown in every Resend-sent email,
 * so the templates don't each carry their own copy of the asset.
 *
 * The logo is inlined as a base64 data URI (256×256 PNG with a transparent
 * background, downscaled from the official GPF email-signature asset) so it
 * renders reliably in email clients that block remote images. Displayed at
 * 72px in the email header, it stays sharp on Retina/2x screens.
 */

const GPF_LOGO_BASE64 = "";

export const GPF_LOGO_DATA_URI = `data:image/png;base64,${GPF_LOGO_BASE64}`;

/** Inline-styled logo <img> tag for email clients. */
export function gpfLogoImg(width = 72): string {
  return `<img src="${GPF_LOGO_DATA_URI}" width="${width}" height="${width}" alt="Give Protocol Foundation" style="display:block;border:0;"/>`;
}

/**
 * Brand header block used by every Resend mailer: white band with the
 * centered emerald logo, matching the bordered content card underneath.
 */
export function gpfBrandHeader(width = 72): string {
  return `  <div style="background:#ffffff;padding:20px;border:1px solid #e5e7eb;border-bottom:none;border-radius:8px 8px 0 0;text-align:center;">
    ${gpfLogoImg(width)}
  </div>`;
}
